const systemA = $input.first().json.system_a;
const systemB = $input.first().json.system_b;

const userPrompt = `SYSTEM A (${systemA.database_name}):
${JSON.stringify(systemA.columns, null, 2)}

SYSTEM B (${systemB.database_name}):
${JSON.stringify(systemB.columns, null, 2)}

Produce the reconciliation mapping as specified.`;

return [{
  json: {
    user_prompt: userPrompt,
    system_a_count: systemA.columns.length,
    system_b_count: systemB.columns.length
  }
}];

const raw = $input.first().json.output || $input.first().json.text || $input.first().json.content;

let parsed;
try {
  // Strip markdown fences defensively in case the model adds them despite instructions
  const cleaned = String(raw).replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error('AI output was not valid JSON. Raw output: ' + String(raw).slice(0, 500));
}

const CONFIDENCE_THRESHOLD = 0.6;
const matched = [];
const needsReview = [];

for (const m of (parsed.mappings || [])) {
  const row = {
    a_columns: (m.a_columns || []).join('; '),
    b_columns: (m.b_columns || []).join('; '),
    confidence: m.confidence,
    match_type: m.match_type,
    reasoning: m.reasoning
  };
  if (m.match_type === 'unmatched' || (m.confidence !== undefined && m.confidence < CONFIDENCE_THRESHOLD)) {
    needsReview.push(row);
  } else {
    matched.push(row);
  }
}

const bOnly = (parsed.b_only_columns || []).map(name => ({
  a_columns: '',
  b_columns: name,
  confidence: null,
  match_type: 'b_only',
  reasoning: 'Present in System B with no System A counterpart.'
}));

return [{
  json: {
    matched,
    needs_review: needsReview.concat(bOnly),
    summary: {
      total_mappings: (parsed.mappings || []).length,
      matched_count: matched.length,
      needs_review_count: needsReview.length,
      b_only_count: bOnly.length
    }
  }
}];
